<?php use Addons\Ong\OngService as S; require __DIR__ . '/_h.php'; $x = $edit ?? []; ?>
<?php if (can('ong.projets')): ?><div class="card mb-3"><div class="card-header"><i class="bi bi-file-earmark-ruled"></i> <?= e(t($x ? 'Modifier la convention' : 'Nouvelle convention de financement')) ?></div><div class="card-body">
<?php if (!$bailleurs || !$projets): ?><p class="text-secondary mb-0"><?= e(t('Créez d\'abord un bailleur et un projet (menu Projets et bailleurs).')) ?></p><?php else: ?>
<form method="post" action="<?= e(url('/ong/conventions')) ?>" class="row g-2"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) ($x['id'] ?? 0) ?>">
  <?= ong_field('number', 'N° de convention', $x['number'] ?? '', 'text', 'required maxlength="60"', 'col-md-2') ?><?= ong_field('title', 'Intitulé', $x['title'] ?? '', 'text', 'required maxlength="180"', 'col-md-4') ?>
  <?= ong_select('bailleur_id', 'Bailleur', ong_opts($bailleurs, 'name', 'Choisir…'), $x['bailleur_id'] ?? '', 'required', 'col-md-3', false) ?><?= ong_select('projet_id', 'Projet', ong_opts($projets, fn ($r) => $r['code'] . ' — ' . $r['name'], 'Choisir…'), $x['projet_id'] ?? '', 'required', 'col-md-3', false) ?>
  <?= ong_field('amount', 'Montant accordé', $x['amount'] ?? '', 'text', 'required inputmode="decimal"', 'col-md-2') ?><?= ong_field('start_date', 'Début', $x['start_date'] ?? '', 'date', 'required', 'col-md-2') ?><?= ong_field('end_date', 'Fin', $x['end_date'] ?? '', 'date', 'required', 'col-md-2') ?>
  <?= ong_select('report_frequency', 'Rapports au bailleur', S::FREQUENCIES, $x['report_frequency'] ?? 'trimestriel', '', 'col-md-2') ?><?= ong_field('overhead_rate', 'Frais administratifs (%)', $x['overhead_rate'] ?? '0', 'text', 'inputmode="decimal"', 'col-md-2') ?><?= ong_select('status', 'État', S::CONV_STATUS, $x['status'] ?? 'active', '', 'col-md-2') ?>
  <?= ong_field('note', 'Conditions particulières', $x['note'] ?? '', 'text', 'maxlength="250"', 'col-md-9') ?>
  <div class="col-md-3 d-flex align-items-end gap-1"><button class="btn btn-sm btn-primary"><i class="bi bi-check-lg"></i> <?= e(t('Enregistrer')) ?></button><?php if ($x): ?><a class="btn btn-sm btn-outline-secondary" href="<?= e(url('/ong/conventions')) ?>"><?= e(t('Annuler')) ?></a><?php endif; ?></div>
</form><?php endif; ?></div></div><?php endif; ?>
<div class="card"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th><?= e(t('Convention')) ?></th><th><?= e(t('Bailleur')) ?></th><th><?= e(t('Projet')) ?></th><th><?= e(t('Période')) ?></th><th class="num"><?= e(t('Montant')) ?></th><th class="num"><?= e(t('Budgété')) ?></th><th class="num"><?= e(t('Reçu')) ?></th><th class="num"><?= e(t('Dépensé')) ?></th><th></th><th></th></tr></thead><tbody>
<?php foreach ($rows as $c): $r = (float) $c['amount'] > 0 ? round((float) $c['spent'] * 100 / (float) $c['amount'], 1) : 0; ?><tr><td><a class="fw-semibold" href="<?= e(url('/ong/conventions/' . $c['id'])) ?>"><?= e($c['number']) ?></a> <?= ong_badge(S::CONV_STATUS[$c['status']], ['negociation' => 'secondary', 'active' => 'success', 'cloturee' => 'dark'][$c['status']]) ?><div class="small text-secondary"><?= e($c['title']) ?></div></td>
  <td class="small"><?= e($c['bailleur']) ?></td><td class="small"><?= e($c['projet_code']) ?></td><td class="small text-nowrap"><?= e(fdate($c['start_date'], false)) ?><br><?= e(fdate($c['end_date'], false)) ?></td>
  <td class="num"><?= money($c['amount']) ?></td><td class="num <?= (float) $c['budgeted'] < (float) $c['amount'] ? 'text-warning' : '' ?>"><?= money($c['budgeted']) ?></td><td class="num"><?= money($c['received']) ?></td><td class="num"><?= money($c['spent']) ?></td><td><?= ong_bar($r) ?><span class="small text-secondary"><?= e((string) $r) ?> %</span></td>
  <td class="text-end"><?php if (can('ong.projets')): ?><a class="btn btn-sm btn-outline-secondary" href="<?= e(url('/ong/conventions', ['edit' => $c['id']])) ?>"><i class="bi bi-pencil"></i></a><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="10" class="text-center text-secondary py-4"><?= e(t('Aucune convention.')) ?></td></tr><?php endif; ?></tbody></table></div></div>
